package com.alsafa.native4;

import android.app.Activity;import android.app.AlertDialog;import android.content.DialogInterface;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.text.InputType;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.CheckBox;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;import com.alsafa.native4.core.RepairWorkflowStore;
/** Delivery settlement UI. A smaller collection is never a discount unless the operator explicitly checks final-price edit and confirms it. */
public final class RepairDeliveryDialog {
 private final Activity a;private final Native4Services services;private final TextView status;public RepairDeliveryDialog(Activity a,Native4Services services,TextView status){this.a=a;this.services=services;this.status=status;}
 public void show(String repairId){try{Repair r=load(repairId);LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);int p=dp(14);box.setPadding(p,p,p,p);TextView agreed=new TextView(a);agreed.setText("المبلغ المتفق عليه: "+fmt(r.total)+" "+r.currency);agreed.setTextSize(18);box.addView(agreed);EditText amount=new EditText(a);amount.setHint("المبلغ الذي سيدفعه العميل الآن");amount.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);amount.setText(fmt(r.total));box.addView(amount,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));CheckBox edit=new CheckBox(a);edit.setText("تعديل السعر النهائي (حسم/زيادة) — وليس دفعة جزئية");box.addView(edit);EditText reason=new EditText(a);reason.setHint("سبب تعديل السعر، مثال: مفاصلة العميل");reason.setVisibility(android.view.View.GONE);box.addView(reason);edit.setOnCheckedChangeListener((b,c)->reason.setVisibility(c?android.view.View.VISIBLE:android.view.View.GONE));Spinner account=new Spinner(a);account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"الدرج","شام كاش","الخزنة الخارجية","البنك"}));box.addView(account);new AlertDialog.Builder(a).setTitle("تسليم الصيانة").setView(box).setNegativeButton("إلغاء",null).setPositiveButton("متابعة",null).create().setOnShowListener(x->{AlertDialog d=(AlertDialog)x;d.getButton(DialogInterface.BUTTON_POSITIVE).setOnClickListener(v->{try{double collected=Double.parseDouble(amount.getText().toString().trim());String acc=accountCode(account.getSelectedItemPosition()),pay="SHAM_CASH".equals(acc)?"SHAM_CASH":"CASH";if("SHAM_CASH".equals(acc)&&"TRY".equals(r.currency))throw new IllegalArgumentException("شام كاش يقبل الدولار والليرة السورية فقط");if(edit.isChecked()&&Math.abs(collected-r.total)>0.000001){confirmAdjustment(d,repairId,r,collected,pay,acc,reason.getText().toString().trim());}else{settle(d,repairId,collected,pay,acc,false,false,"");}}catch(Exception e){status.setText("تعذر التسليم: "+msg(e));}});});AlertDialog d=new AlertDialog.Builder(a).setTitle("تسليم الصيانة").setView(box).setNegativeButton("إلغاء",null).setPositiveButton("متابعة",null).create();d.setOnShowListener(x->d.getButton(DialogInterface.BUTTON_POSITIVE).setOnClickListener(v->{try{double collected=Double.parseDouble(amount.getText().toString().trim());String acc=accountCode(account.getSelectedItemPosition()),pay="SHAM_CASH".equals(acc)?"SHAM_CASH":"CASH";if("SHAM_CASH".equals(acc)&&"TRY".equals(r.currency))throw new IllegalArgumentException("شام كاش يقبل الدولار والليرة السورية فقط");if(edit.isChecked()&&Math.abs(collected-r.total)>0.000001)confirmAdjustment(d,repairId,r,collected,pay,acc,reason.getText().toString().trim());else settle(d,repairId,collected,pay,acc,false,false,"");}catch(Exception e){status.setText("تعذر التسليم: "+msg(e));}}));d.show();}catch(Exception e){status.setText("تعذر فتح التسليم: "+msg(e));}}
 private void confirmAdjustment(AlertDialog parent,String id,Repair r,double amount,String pay,String acc,String reason){double diff=Math.abs(r.total-amount);String kind=amount<r.total?"حسم للعميل":"زيادة على السعر";String text="المبلغ المتفق عليه "+fmt(r.total)+" "+r.currency+"، والمبلغ النهائي "+fmt(amount)+" "+r.currency+". سيتم تسجيل "+fmt(diff)+" "+r.currency+" "+kind+". هل تريد التأكيد؟";new AlertDialog.Builder(a).setTitle("تأكيد تعديل السعر").setMessage(text).setNegativeButton("رجوع",null).setPositiveButton("تأكيد",(x,w)->{try{settle(parent,id,amount,pay,acc,true,true,reason);}catch(Exception e){status.setText("تعذر تعديل السعر: "+msg(e));}}).show();}
 private void settle(AlertDialog d,String id,double amount,String pay,String acc,boolean edit,boolean confirmed,String reason)throws Exception{RepairWorkflowStore.Settlement s=services.repairs.collect(id,amount,pay,acc,edit,confirmed,reason);if(s.balanceDue<=0.000001)services.repairs.setStatus(id,"DELIVERED");Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();d.dismiss();if(edit)status.setText("✓ تم التسليم — النهائي "+fmt(s.finalTotal)+" "+s.currency+" — الحسم "+fmt(s.customerDiscount));else status.setText("✓ تم تسجيل الدفعة "+fmt(s.collected)+" "+s.currency+" — المتبقي "+fmt(s.balanceDue));}
 private Repair load(String id){SQLiteDatabase db=services.db.db();try(Cursor c=db.rawQuery("SELECT total,currency FROM repairs WHERE repair_id=? AND deleted_at IS NULL",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("الصيانة غير موجودة");return new Repair(c.getDouble(0),c.getString(1));}}
 private static String accountCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";return "MAIN";}private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}private static final class Repair{final double total;final String currency;Repair(double t,String c){total=t;currency=c;}}
}
